#!/usr/bin/env bash
# Some of these repos TRACK build artifacts that our use inevitably rewrites:
#   * <pkg>.egg-info/  -- regenerated by `pip install -e`
#   * __pycache__/*.pyc -- rewritten the first time we import the package
# So merely installing and importing dirties the repo through no fault of ours.
# skip-worktree tells git to ignore local changes to exactly those paths without
# touching .gitignore or the files themselves, which keeps the zero-upstream-edit
# invariant mechanically checkable rather than aspirational.
set -euo pipefail
EMB_ROOT="${EMB_ROOT:-/data/jyc/space/Embodied AI}"
for repo in openvla VLA-Adapter FastWAM; do
  d="$EMB_ROOT/$repo"
  [ -d "$d/.git" ] || continue
  mapfile -t files < <(git -C "$d" ls-files | grep -E '(\.egg-info/|__pycache__/)' || true)
  [ ${#files[@]} -eq 0 ] && continue
  git -C "$d" checkout -- "${files[@]}" 2>/dev/null || true
  git -C "$d" update-index --skip-worktree "${files[@]}"
  echo "$repo: protected ${#files[@]} tracked build artifact(s)"
done
